CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(64) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,nickname VARCHAR(80) NOT NULL,role VARCHAR(16) NOT NULL DEFAULT 'USER',balance_cents BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT positive_balance CHECK(balance_cents>=0));
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,category VARCHAR(64) NOT NULL,category_name VARCHAR(80) NOT NULL,description TEXT NOT NULL,price_cents BIGINT NOT NULL,original_price_cents BIGINT NOT NULL,image_url VARCHAR(1024) NOT NULL,specifications TEXT NOT NULL,tags TEXT NOT NULL,manual_url VARCHAR(1024) NOT NULL DEFAULT '',featured BOOLEAN NOT NULL DEFAULT FALSE,enabled BOOLEAN NOT NULL DEFAULT TRUE,sold BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT positive_price CHECK(price_cents>0));
CREATE INDEX idx_products_category ON products(category,enabled);
CREATE TABLE inventory (product_id BIGINT PRIMARY KEY,stock INT NOT NULL DEFAULT 0,reserved INT NOT NULL DEFAULT 0,CONSTRAINT fk_inventory_product FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT positive_stock CHECK(stock>=0 AND reserved>=0));
CREATE TABLE cart_items (user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT positive_quantity CHECK(quantity>0));
CREATE TABLE orders (id VARCHAR(36) PRIMARY KEY,order_no VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT NOT NULL,status VARCHAR(32) NOT NULL,total_cents BIGINT NOT NULL,address_json TEXT NOT NULL,request_key VARCHAR(100) NOT NULL,request_hash VARCHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,paid_at TIMESTAMP NULL,tracking_no VARCHAR(100) NULL,UNIQUE(user_id,request_key),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_orders_user ON orders(user_id,created_at);
CREATE INDEX idx_orders_expiry ON orders(status,expires_at);
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id VARCHAR(36) NOT NULL,product_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,image_url VARCHAR(1024) NOT NULL,price_cents BIGINT NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE wallet_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,type VARCHAR(32) NOT NULL,amount_cents BIGINT NOT NULL,balance_after_cents BIGINT NOT NULL,reference_id VARCHAR(100) NOT NULL,reason VARCHAR(250) NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,type,reference_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE inventory_adjustments (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,request_key VARCHAR(100) NOT NULL UNIQUE,delta INT NOT NULL,reason VARCHAR(250) NOT NULL,admin_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE event_outbox (id VARCHAR(36) PRIMARY KEY,topic VARCHAR(80) NOT NULL,event_type VARCHAR(80) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TIMESTAMP NULL,attempts INT NOT NULL DEFAULT 0);
CREATE INDEX idx_outbox_pending ON event_outbox(sent_at,created_at);
